$('#property-filter').onchange=async e=>{S.property=e.target.value;S.focusScope='auto';if(S.view==='records')await renderRecords();else await navigate(S.view==='shop'&&S.props.find(p=>p.property_id===S.property)?.data.business!=='commerce'?'overview':S.view);};
