const sectorUI=createSectors({state:()=>S,api,modal,toast,navigate,editRecord,openKind,download,esc,fmt,pct,text,table,panel,metric,propName});
const commerceUI=createCommerce({state:()=>S,modal,toast,navigate,editRecord,openKind,esc,fmt,pct,text,table,panel,metric,propName});
